{
  "name": "Newport ESP300多轴运动控制器",
  "name_en": "Newport ESP300 Multi-Axis Motion Controller",
  "manufacturer": "Newport",
  "description": "这是一台用于驱动和控制多轴电动位移台或旋转台的实验室运动控制器，常见于显微镜、光学平台和精密定位系统中，用于样品、物镜或光学元件的精确移动与定位。",
  "description_en": "This is a laboratory multi-axis motion controller used to drive motorized translation or rotation stages. It is commonly used in microscopes, optical benches, and precision positioning setups to move and position samples, objectives, or optical components accurately.",
  "tag_hints": [
    "multi-axis motion control",
    "motorized stage",
    "precision positioning",
    "translation stage",
    "optical alignment",
    "microscopy positioning",
    "serial motion controller"
  ],
  "actions": [
    {
      "action_name": "auto-stop_all",
      "description": "紧急停止所有运动轴。",
      "description_en": "Emergency-stop all motion axes."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道或运动轴移动到目标位置。",
      "description_en": "Move the specified channel or motion axis to a target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定通道或运动轴的当前位置。",
      "description_en": "Get the current position of the specified channel or motion axis."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制器是否就绪。",
      "description_en": "Get whether the controller is ready."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取指定运动通道。",
      "description_en": "Get the specified motion channel."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取指定通道的相位状态。",
      "description_en": "Get the phase status of the specified channel."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道或运动轴的最小位置限制。",
      "description_en": "Get the minimum position limit of the specified channel or motion axis."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道或运动轴的最大位置限制。",
      "description_en": "Get the maximum position limit of the specified channel or motion axis."
    },
    {
      "action_name": "auto-ledOn",
      "description": "打开关联的LED。",
      "description_en": "Turn on the associated LED."
    },
    {
      "action_name": "auto-ledOff",
      "description": "关闭关联的LED。",
      "description_en": "Turn off the associated LED."
    },
    {
      "action_name": "auto-addMenuItems",
      "description": "添加用于运动轴和LED控制的菜单项。",
      "description_en": "Add menu items for motion-axis and LED control."
    }
  ]
}

